 services.forEach(service=>{
  const manage=document.getElementById('manage-'+service.id);
  const select=manage?.querySelector('select[name="product_id"]');
  if(select)[...select.options].forEach(option=>{const matches=products[option.value]===service.provider;option.hidden=!matches;option.disabled=!matches;});
  if(service.provider==='linode'&&manage){
   const grid=manage.querySelector('.resource-grid');if(grid)grid.hidden=true;
   const resourceButton=manage.querySelector('button[value="edit_resources"]');if(resourceButton)resourceButton.hidden=true;
   const rule=grid?.previousElementSibling;if(rule&&rule.tagName==='HR')rule.hidden=true;
  }
  const termination=document.getElementById('terminate-'+service.id);
  const explanation=termination?.querySelector('p');
  if(explanation)explanation.textContent=service.provider==='linode'?'This permanently deletes the Linode VPS and cannot be undone.':'This permanently deletes the Pterodactyl server and cannot be undone.';
 });
})();
</script>
<section class="card" style="margin-top:20px"><div class="cardhead"><b>RECENT SERVICE ACTIVITY</b><span class="muted">Last 30 actions</span></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>When</th><th>Service</th><th>Admin</th><th>Action</th><th>Details</th></tr></thead><tbody><?php if(!$activity):?><tr><td colspan="5" class="muted">No activity recorded yet.</td></tr><?php endif?><?php foreach($activity as $a):?><tr><td><?=e($a['created_at'])?></td><td><?=e($a['service_name']??('#'.$a['service_id']))?></td><td><?=e($a['admin_name']??'System')?></td><td><?=admin_badge($a['action'])?></td><td><?=e($a['details']??'')?></td></tr><?php endforeach?></tbody></table></div></section>
<?php admin_foot(); ?>
